<script lang="ts">
import {onMount,tick} from 'svelte';import AppointmentChase from './AppointmentChase.svelte';import Icon from './Icon.svelte';import {openPublicLink} from './bridge';
let {version,language,t,update=null,updateState='idle',oncheck=()=>{},onclose}:{version:string;language:string;t:(key:string)=>string;update?:{latest:string|null;available:boolean}|null;updateState?:'idle'|'checking'|'failed';oncheck?:()=>void;onclose:()=>void}=$props();
let dialog:HTMLDialogElement;let failed=$state(false);let clicks=0;let chase=$state(false);
function versionClick(){clicks++;if(clicks===5){clicks=0;chase=true;}}
onMount(()=>{dialog.showModal();dialog.querySelector<HTMLButtonElement>('.github-link')?.focus();return()=>dialog.close();});
async function back(){chase=false;await tick();dialog.querySelector<HTMLButtonElement>('.github-link')?.focus();}
async function open(target:'github'|'readme'|'issues'|'releases'){failed=false;try{await openPublicLink(target,language);}catch{failed=true;}}
</script>
<dialog class="about-dialog" class:playing={chase} bind:this={dialog} oncancel={e=>{e.preventDefault();if(chase)void back();else onclose();}}>{#if chase}<AppointmentChase {language} {t} onback={()=>void back()}/>{:else}<div class="about-identity"><img src="/santacita-icon.svg" alt="" width="58" height="58"/><div><h1>SantaCita</h1><button type="button" class="version muted" tabindex="-1" onclick={versionClick}>{t('Версия')} {version} · Rust Preview</button></div></div><p class="description">{t('Помощник для поиска сит в Extranjería: отпечатки пальцев / TIE и Autorización de regreso.')}</p>
<section class="about-updates"><Icon name="shield"/><div class="update-text"><h2>{t('Обновления')}</h2><p class="muted" role="status">{#if updateState==='checking'}{t('Проверяем обновления…')}{:else if updateState==='failed'}{t('Не удалось проверить обновления')}{:else if update?.available}{t('Доступна новая версия')}: {update.latest}{:else if update}{t('Последняя версия')}: {update.latest} · {t('Установлена актуальная версия')}{:else}{t('Последняя версия')}: {t('Ещё не проверена')}{/if}</p></div>{#if update?.available}<button class="primary" onclick={()=>void open('releases')}><Icon name="download" size={16}/>{t('Открыть страницу релиза')}</button>{/if}<button disabled={updateState==='checking'} onclick={oncheck}>{t('Проверить')}</button></section>
<div class="about-links"><button class="github-link" onclick={()=>void open('github')}><img src="/social/github.svg" alt="" width="18" height="18"/>GitHub</button><button onclick={()=>void open('readme')}><Icon name="book" size={18}/>{t('Как пользоваться')}</button><button onclick={()=>void open('issues')}><Icon name="bug" size={18}/>{t('Сообщить о проблеме')}</button></div>
{#if failed}<p class="error" role="alert">{t('Не удалось открыть ссылку')}</p>{/if}
<div class="about-footer"><p class="muted">{t('Независимый проект')}<br/>{t('Данные хранятся локально')}</p><button onclick={onclose}>{t('Закрыть')}</button></div>{/if}</dialog>
<style>.about-updates{display:flex;align-items:center;gap:12px}.update-text{flex:1;min-width:0}.about-updates .primary{background:var(--accent);border-color:var(--accent);color:white}.about-dialog{width:min(560px,calc(100vw - 32px));padding:24px;background:var(--bg);color:var(--text);border:1px solid var(--strong);border-radius:12px;max-height:calc(100vh - 32px);overflow:auto}.about-dialog::backdrop{background:#0008}.about-identity{display:flex;gap:14px;align-items:center}.about-identity h1{font-size:21px;margin:0;font-weight:600}.about-dialog.playing{height:min(460px,calc(100dvh - 32px))}.version{cursor:default;user-select:none;font-size:12px;margin:5px 0 0;padding:0;background:none;border:0;min-height:0;font-weight:400}.version:hover{background:none}.version:focus-visible{outline:none;box-shadow:none}.description{font-size:13px;line-height:1.55;margin:18px 0}.about-updates{border:1px solid var(--line);background:var(--surface);border-radius:7px;display:flex;align-items:center;gap:12px;padding:14px}.about-updates h2{font-size:14px;margin:0 0 5px}.about-updates p{font-size:12px;margin:0;line-height:1.4}.about-links{display:grid;grid-template-columns:8fr 11fr 15fr;gap:8px;margin-top:14px}.about-links button{font-size:12px;padding:9px 6px;white-space:nowrap;justify-content:center}.about-footer{display:flex;align-items:center;justify-content:space-between;margin-top:18px;gap:16px}.about-footer p{font-size:12px;line-height:1.6;margin:0}.github-link img{filter:none}:global(.app-shell:not(.light)) .github-link img{filter:invert(1)}</style>
